-- M03-T02 Increment 1 — identity and rate-limit schema (docs/IMPLEMENTATION_PLAN.md
-- M03-T01 record; docs/DECISIONS.md ADR-011). Authored per ADR-010: generated by
-- `prisma migrate diff --from-config-datasource --to-schema prisma/schema.prisma
-- --script` against landmarks_test on 2026-11-07, then hand-reviewed and
-- hand-finished, and applied only via `prisma migrate deploy`.
--
-- Two statements the diff tool proposed were DISCARDED, exactly as ADR-010
-- anticipates: `DROP INDEX "landmarks_location_gist_idx"` and
-- `ALTER TABLE "landmarks" ALTER COLUMN "location" DROP NOT NULL`. Both are the
-- known shadow-database diffing artefact against the hand-written GENERATED
-- `location` column, not real drift. This migration touches NOTHING on
-- `landmarks` — no table, column, index, constraint, trigger, or row.
--
-- Everything else below is the diff tool's unmodified output for the five new
-- tables, followed by two hand-written indexes Prisma's schema language cannot
-- express (same pattern as the `landmarks` CHECK constraints and GiST index).

-- CreateTable
-- Better Auth core `user` model (field set from packages/core/src/db/get-tables.ts
-- at tag v1.7.18). `name` is required by the library and forced to '' by the
-- application's user-creation hook (ADR-011 decision 3).
CREATE TABLE "users" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "email_verified" BOOLEAN NOT NULL DEFAULT false,
    "image" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);

-- CreateTable
-- Better Auth core `session` model. `ip_address`/`user_agent` are kept nullable
-- for schema compatibility and blanked by the session-creation hook (ADR-011
-- decision 4). Cascade from users is permitted here: this is Better Auth's own
-- identity data, not application data (ADR-011 decision 7).
CREATE TABLE "sessions" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "token" TEXT NOT NULL,
    "expires_at" TIMESTAMP(3) NOT NULL,
    "ip_address" TEXT,
    "user_agent" TEXT,
    "user_id" UUID NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "sessions_pkey" PRIMARY KEY ("id")
);

-- CreateTable
-- Better Auth core `account` model. The scrypt password hash lives ONLY here
-- (provider_id = 'credential', account_id = the user's id). The OAuth token
-- columns are never populated (no OAuth providers) but must exist for the
-- library's startup schema validation.
CREATE TABLE "accounts" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "account_id" TEXT NOT NULL,
    "provider_id" TEXT NOT NULL,
    "user_id" UUID NOT NULL,
    "access_token" TEXT,
    "refresh_token" TEXT,
    "id_token" TEXT,
    "access_token_expires_at" TIMESTAMP(3),
    "refresh_token_expires_at" TIMESTAMP(3),
    "scope" TEXT,
    "password" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "accounts_pkey" PRIMARY KEY ("id")
);

-- CreateTable
-- Better Auth core `verification` model (password-reset tokens, etc.).
CREATE TABLE "verifications" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "identifier" TEXT NOT NULL,
    "value" TEXT NOT NULL,
    "expires_at" TIMESTAMP(3) NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "verifications_pkey" PRIMARY KEY ("id")
);

-- CreateTable
-- Better Auth database-backed rate-limit storage (model `rateLimit`), approved
-- for M03-T02 and recorded as the ADR-011 amendment. `last_request` is an
-- epoch-milliseconds value per the library's schema.
CREATE TABLE "rate_limits" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "key" TEXT NOT NULL,
    "count" INTEGER NOT NULL,
    "last_request" BIGINT NOT NULL,

    CONSTRAINT "rate_limits_pkey" PRIMARY KEY ("id")
);

