-- ---------------------------------------------------------------------------
-- Hand-written (ADR-011 decisions 5 and 6; Prisma has no declarative syntax for
-- functional or partial indexes).
-- ---------------------------------------------------------------------------

-- CreateIndex (hand-written)
-- Case-insensitive email uniqueness at the database, independent of Better
-- Auth's own lowercasing on sign-up/sign-in — also guards any write that
-- bypasses the library.
CREATE UNIQUE INDEX "users_email_lower_key" ON "users" (lower("email"));

-- CreateIndex (hand-written)
-- One credential (email/password) account per user, stated directly rather than
-- relying on the library's account_id-equals-user-id convention.
CREATE UNIQUE INDEX "accounts_credential_user_key" ON "accounts" ("user_id") WHERE "provider_id" = 'credential';
